### 6. Server-side service implementation

Create `ShipmentTracker/Services/ShipmentServerService.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(IServiceProvider serviceProvider) : IShipmentService
{
    public async Task<List<ShipmentSummary>> GetAllShipmentsAsync()
    {
        using var scope = serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        return await db.Shipments.Select(s => new ShipmentSummary
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail
        }).ToListAsync();
    }

    public async Task<ShipmentSummary?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        using var scope = serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var s = await db.Shipments.FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
        if (s is null) return null;
        return new ShipmentSummary
        {
            Id = s.Id,
            TrackingNumber = s.TrackingNumber,
            Origin = s.Origin,
            Destination = s.Destination,
            Status = s.Status,
            EstimatedDelivery = s.EstimatedDelivery,
            CustomerEmail = s.CustomerEmail
        };
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus newStatus)
    {
        using var scope = serviceProvider.CreateScope();
        var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is not null)
        {
            shipment.Status = newStatus;
            await db.SaveChangesAsync();
        }
    }
}
```

### 7. API Endpoints

Create `ShipmentTracker/Endpoints/ShipmentEndpoints.cs`:
```csharp
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            return await db.Shipments.Select(s => new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status,
                EstimatedDelivery = s.EstimatedDelivery,
                CustomerEmail = s.CustomerEmail
            }).ToListAsync();
        });

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var s = await db.Shipments.FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
            if (s is null) return Results.NotFound();
            return Results.Ok(new ShipmentSummary
            {
                Id = s.Id,
                TrackingNumber = s.TrackingNumber,
                Origin = s.Origin,
                Destination = s.Destination,
                Status = s.Status,
                EstimatedDelivery = s.EstimatedDelivery,
                CustomerEmail = s.CustomerEmail
            });
        });

        group.MapPut("/{id}/status", async (int id, ShipmentStatus newStatus, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments.FindAsync(id);
            if (shipment is null) return Results.NotFound();
            shipment.Status = newStatus;
            await db.SaveChangesAsync();
            return Results.NoContent();
        });
    }
}
```

